  const platformSettingDefinitions:Record<string,{value:any;description:string}>={maintenance_mode:{value:false,description:'Place public platform actions into maintenance mode'},registration_enabled:{value:true,description:'Allow creation of new user accounts'},platform_announcement:{value:{enabled:false,title:'',message:''},description:'Platform-wide announcement content'},matchmaking_defaults:{value:{gameMode:'classic-deathmatch',selectedMaps:['dm_crossfire'],queueTimeoutMinutes:15},description:'Default matchmaking mode, maps, and queue timeout'},xp_defaults:{value:{win:50,loss:10},description:'Default match XP rewards'},points_defaults:{value:{startingBalance:1000,win:0,loss:0},description:'Default account and match point rewards'}}
  const validatePlatformSetting=(key:string,value:any)=>{if(!platformSettingDefinitions[key])throw new Error(`Unsupported platform setting: ${key}`);if(['maintenance_mode','registration_enabled'].includes(key)){if(typeof value!=='boolean')throw new Error(`${key} must be boolean`);return value}if(!value||Array.isArray(value)||typeof value!=='object')throw new Error(`${key} must be an object`);if(key==='platform_announcement'){if(typeof value.enabled!=='boolean'||typeof value.title!=='string'||typeof value.message!=='string')throw new Error('Announcement enabled, title, and message are required');if(value.title.length>120||value.message.length>2000)throw new Error('Announcement title or message is too long');if(value.enabled&&(!value.title.trim()||!value.message.trim()))throw new Error('Enabled announcements require a title and message');return{enabled:value.enabled,title:value.title.trim(),message:value.message.trim()}}if(key==='matchmaking_defaults'){if(!['classic-deathmatch','instagib-mode'].includes(value.gameMode))throw new Error('Invalid default game mode');if(!Array.isArray(value.selectedMaps)||!value.selectedMaps.length||value.selectedMaps.length>32||value.selectedMaps.some((map:any)=>typeof map!=='string'||!map.trim()))throw new Error('Default matchmaking maps must contain 1-32 map names');const timeout=Number(value.queueTimeoutMinutes);if(!Number.isInteger(timeout)||timeout<1||timeout>1440)throw new Error('Queue timeout must be between 1 and 1440 minutes');return{gameMode:value.gameMode,selectedMaps:[...new Set(value.selectedMaps.map((map:string)=>map.trim()))],queueTimeoutMinutes:timeout}}const fields=key==='xp_defaults'?['win','loss']:['startingBalance','win','loss'];const normalized:any={};for(const field of fields){const amount=Number(value[field]);if(!Number.isInteger(amount)||amount<0||amount>1000000)throw new Error(`${key}.${field} must be an integer between 0 and 1000000`);normalized[field]=amount}return normalized}
